Here's a TypeScript React component with Tailwind CSS that implements the layout component with two variants:

```tsx
import { ReactNode } from 'react';

type LayoutProps = {
  children: ReactNode;
  className?: string;
  variant?: 'full-width' | 'centered';
};

export function Layout({ children, className = '', variant = 'centered' }: LayoutProps) {
  const baseClasses = 'w-full';

  const variantClasses = {
    'full-width': 'max-w-full',
    'centered': 'max-w-[1280px] mx-auto',
  };

  return (
    <div className={`${baseClasses} ${variantClasses[variant]} ${className}`}>
      {children}
    </div>
  );
}
```

Usage examples:

```tsx
