<Layout>
  <h1>Welcome</h1>
  <p>This content is centered with max-width 1280px</p>
</Layout>

// Full-width layout
<Layout variant="full-width">
  <h1>Full Width Content</h1>
  <p>This content spans the full width</p>
</Layout>

// With custom className
<Layout variant="centered" className="bg-gray-100 p-4">
  <h1>Styled Layout</h1>
</Layout>
```

