            try
            {
                // Get the target entity
                Entity target = (Entity)context.InputParameters["Target"];

                // Check if the user has the "MyCustomRole" security role
                bool hasRole = false;
                var userRoles = service.RetrieveMultiple(
                    new QueryExpression("systemuserroles")
                    {
                        ColumnSet = new ColumnSet("roleid"),
                        Criteria = new FilterExpression
                        {
                            Conditions =
                            {
                                new ConditionExpression("systemuserid", ConditionOperator.Equal, context.UserId)
                            }
                        }
                    });

                foreach (var userRole in userRoles.Entities)
                {
                    var role = service.Retrieve("role", userRole.GetAttributeValue<Guid>("roleid"), new ColumnSet("name"));
                    if (role.GetAttributeValue<string>("name") == "MyCustomRole")
                    {
                        hasRole = true;
                        break;
                    }
                }

                // Set the field to true if the user has the role
                if (hasRole)
                {
                    target["new_customfield"] = true;
                }
            }
            catch (Exception ex)
            {
                tracingService.Trace("Error: {0}", ex.ToString());
                throw new InvalidPluginExecutionException("An error occurred in the plugin.", ex);
            }
        }
    }
}
